-- Db2 table partitioning clauses for CREATE TABLE.
-- https://www.ibm.com/docs/en/db2/11.5?topic=statements-create-table

CREATE TABLE t (id INT)
PARTITION BY RANGE (id)
(STARTING 1 ENDING 99 EVERY 10, STARTING 100 ENDING 199);

CREATE TABLE orders (order_id INT, order_date DATE)
PARTITION BY RANGE (order_date)
(
    STARTING '2024-01-01' ENDING '2024-12-31' EVERY 1 MONTH,
    STARTING '2025-01-01' ENDING '2025-12-31' EVERY 1 MONTH
);

CREATE TABLE sales (sale_id INT)
PARTITION BY RANGE (sale_id)
(
    PARTITION p_small STARTING MINVALUE ENDING 999,
    PARTITION p_medium STARTING 1000 ENDING 9999,
    PARTITION p_large STARTING 10000 ENDING MAXVALUE
);

CREATE TABLE measurements (id INT, ts TIMESTAMP)
PARTITION BY RANGE (ts)
(
    PARTITION p0 STARTING FROM ('2024-01-01-00.00.00') INCLUSIVE ENDING AT ('2024-06-30-23.59.59') INCLUSIVE,
    PARTITION p1 STARTING ('2024-07-01-00.00.00') ENDING ('2024-12-31-23.59.59') EVERY (1 MONTH)
);

CREATE TABLE events (event_id INT, event_date DATE)
PARTITION BY RANGE (event_date)
(
    STARTING '2024-01-01' ENDING '2024-03-31' IN ts_q1,
    STARTING '2024-04-01' ENDING '2024-06-30' IN ts_q2 INDEX IN ts_idx_q2,
    STARTING '2024-07-01' ENDING MAXVALUE
);

CREATE TABLE multi_key (a INT, b INT)
PARTITION BY RANGE (a NULLS LAST, b)
(
    STARTING (1, 1) ENDING (10, 10) EVERY (10),
    STARTING (11, 11) ENDING (MAXVALUE, MAXVALUE)
);

CREATE TABLE with_nulls (id INT, val INT)
PARTITION BY RANGE (val NULLS FIRST)
(
    STARTING MINVALUE ENDING 0,
    STARTING 1 ENDING MAXVALUE
);

CREATE TABLE negative_bounds (id INT)
PARTITION BY RANGE (id)
(
    STARTING -100 ENDING 0,
    STARTING 1 ENDING MAXVALUE
);

CREATE TABLE partitioned_t (id INT)
IN ts
PARTITION BY RANGE (id)
(STARTING 1 ENDING 100 IN ts_p1, STARTING 101 ENDING MAXVALUE IN ts_p2)
ORGANIZE BY ROW
COMPRESS YES ADAPTIVE;
